export const initialState = Object.freeze({load:'row', futureClosed:false, stepdown:'hall', rowCount:3, meter:'facility', powerFactor:.9, balanced:true, reserve:.2, placement:'rack', conversionEfficiency:.975, moved:false, weather:'normal', decision:'service', reveal:false});
const read = id => `../index.html#d04-${id}`;
const scene = (id,title,role,objective,reference,explanation,extra={}) => ({id,label:title,title,pedagogical_role:role,objectives:[objective],reference:read(reference),explanation,...extra});
export const learning_contract = Object.freeze({
  driving_question:'Can the next hall use the power available at the campus connection?',
  fixed_boundary:'Campus AC connection to IT DC output, with cooling and building loads counted on their own branches.',
  changed_variable:'Selected load path, transformer location, branch load, power factor, conversion placement and a proposed phase extension.',
  primary_payoff:'Trace the whole path and compare demand with each limit at the same boundary.',
  misconception:'A campus MW total or an empty tap-off position guarantees usable power at a rack.',
  closing_question:'Which combination of upstream and downstream changes releases a 0.5 MW IT extension?',
});
export const scenes = [
  scene('distribution-purpose','Can the next hall use the campus power?','problem','D04.1','read-the-power-train','A campus connection feeds a branching electrical network. Follow where voltage changes, where loads share conductors, and where each rating applies before approving another hall.'),
  scene('abilene-distribution','Abilene needs a complete path to every hall','problem','D04.1','read-the-power-train','Return to the original Oracle/OpenAI campus in Abilene, shown in Oracle’s July 15, 2026 data-hall aerial. A supply connection must become a complete distribution path to each load. The public photograph does not establish feeder routes or equipment ratings; use the following defined campus model to learn how to read those details.',{case:'abilene'}),
  scene('campus-route','Trace one load back to the connection','architecture','D04.1','read-the-power-train','Select the rack or cooling pump. Their paths share a campus feeder and a building bus, then separate. The future hall has its own open feeder. A drawn route only supplies a load when the required connections exist and are in the stated operating condition.',{controls:[{key:'load',label:'Load',options:[['row','Rack'],['cooling','Cooling pump'],['future','Future hall']]}]}),
  scene('one-line','One line can represent a three-phase circuit','mechanism','D04.1','read-the-power-train','The single-line drawing compresses multiphase connections. The expanded low-voltage example shows three phases, neutral and protective earth. Neutral carries return current for phase-to-neutral loads; protective earth has a different job. Neither is an extra phase.'),
  scene('feeder-switching','A switch changes the connection','mechanism','D04.1','read-the-power-train','Here a circuit breaker connects or disconnects one feeder from the bus. It does not change AC voltage. A measurement system and protection logic can command a suitable breaker to interrupt a fault; the enclosure also provides insulation and separation. The slide switches an unloaded future feeder in a teaching model.',{controls:[{key:'futureClosed',label:'Future feeder',options:[[false,'Open'],[true,'Closed']]}]}),
  scene('compass-skid','Compass puts switchgear and a transformer on one skid','architecture','D04.1','read-the-power-train','Siemens and Compass co-developed an integrated medium-voltage skid using 8DJH 36 switchgear and a transformer. The package combines functions without merging them: switchgear manages connections, while the transformer changes voltage. The photograph shows the switchgear portion in the factory. Its product-family name does not establish the actual site voltage.',{case:'compass'}),
  scene('transformer','A transformer trades voltage for current','mechanism','D04.1','read-the-power-train','Changing magnetic flux links insulated windings. The turns ratio sets the approximate AC voltage ratio; power transferred to the secondary requires corresponding primary power plus losses. Core and winding loss become local heat. A conventional transformer does not rectify AC.'),
  scene('local-stepdown','Put the high-current route close to the hall','comparison','D04.2','current-and-rating','Keep a balanced 2 MW load, PF 1, and both voltage levels fixed. Moving the step-down transformer from the campus entrance to the hall changes which voltage crosses the 450 m route. At 13.8 kV that route carries about 84 A; at 480 V it carries about 2,406 A. Cable, insulation and equipment requirements change with the route; these currents do not establish actual losses.',{controls:[{key:'stepdown',label:'Transformer location',options:[['entrance','Campus entrance'],['hall','Beside the hall']]}]}),
  scene('building-branches','The building bus feeds more than IT','architecture','D04.1','read-the-power-train','The low-voltage switchboard collects an incoming supply on busbars and distributes it through outgoing circuits. Cooling, lighting, controls and IT are separate loads. Where a UPS belongs depends on which loads require its service; the normal-flow diagram leaves that continuity function as an identified block.'),
  scene('distribution-units','Read what the PDU actually does','comparison','D04.1','read-the-power-train','A floor power distribution unit may package a transformer, branch breakers and metering. A rack PDU commonly distributes an existing AC supply to server outlets. The name alone cannot tell you whether voltage changes. Follow the labeled input and output of the selected equipment.'),
  scene('fujitsu-busway','Fujitsu moved new circuits above the racks','comparison','D04.1','read-the-power-train','For an expansion of a managed 3.2 MW data center north of London, Fujitsu selected 250 A Starline Track Busway. Its existing hall used cables below the floor; the new design kept that space available for cooling and added metering at tap-offs. A movable branch connection shortened the work of accommodating changing rack requirements.',{case:'fujitsu'}),
  scene('busway-branches','A tap-off creates a branch from a shared bus','mechanism','D04.1','read-the-power-train','An end feed supplies the busway conductors. A tap-off makes a branch with its specified protection and connector, then a short cord supplies the rack. The bus carries the sum of the downstream loads. A busway and a cable both have conductor and thermal constraints; their physical arrangement and branch installation differ.'),
  scene('row-growth','A new tap-off still uses the same upstream conductors','counterexample','D04.2','current-and-rating','The row example uses 415 V balanced three-phase, PF 1 and a supplied 250 A usable budget. Three 40 kW racks require 167 A at the end feed. A fourth raises it to 223 A, although each rack branch still carries about 56 A. A fifth would need about 278 A. Spare physical tap positions do not add current capacity.',{controls:[{key:'rowCount',label:'Connected racks',options:[[3,'Three × 40 kW'],[4,'Four × 40 kW'],[5,'Five × 40 kW']]}]}),
  scene('meter-boundary','A meter counts the loads behind it','mechanism','D04.4','read-the-power-train','The facility meter includes IT, electrical losses and auxiliaries. The IT output meter excludes upstream loss and separately fed pumps. Neither number is wrong. The meter boundary determines which electrical account it answers.',{controls:[{key:'meter',label:'Meter',options:[['facility','Facility input'],['it','IT output']]}]}),
  scene('output-to-input','Work backward from the required DC output','balance','D04.2','current-and-rating','A 900 kW DC output at 96% conversion efficiency requires 937.5 kW real input. The 37.5 kW difference is converter heat. Divide by efficiency when moving toward the source; losses cannot supply the load.'),
  scene('apparent-power','Power factor changes the current needed for real power','mechanism','D04.2','current-and-rating','Apparent power uses AC voltage and current magnitudes; power factor is real power divided by apparent power. At PF 0.90, the same 937.5 kW input needs 1,041.7 kVA. The difference between kVA and kW is not a heat term. Use total power factor when current is distorted.'),
  scene('current-rating','Compare a kVA rating with the kVA demand','balance','D04.2','current-and-rating','At 480 V line-to-line RMS, a balanced three-phase input of 1,041.7 kVA needs about 1,253 A. It exceeds the supplied 1,000 kVA transformer limit even though real input is below 1,000 kW. The calculation is a rating screen at the specified operating point.'),
  scene('power-factor','Change power factor and watch the AC side','comparison','D04.2','current-and-rating','Keep DC output at 900 kW and conversion efficiency at 96%. Improving the supplied input PF from 0.90 to 0.99 reduces current and apparent power, while modeled real input and converter heat stay fixed. Actual upstream copper losses can fall as current falls; they are outside this converter-only balance.',{controls:[{key:'powerFactor',label:'Input power factor',options:[[.9,'0.90'],[.99,'0.99']]}]}),
  scene('phase-loading','An average can hide the overloaded phase','counterexample','D04.2','current-and-rating','Each phase conductor has a supplied 400 A usable limit. A 380 A average can describe either three 380 A phases or a 460/350/330 A imbalance. In the latter case phase A exceeds its limit. Redistribute compatible phase-to-neutral branches only with the electrical design and actual phase measurements; total load alone misses the problem.',{controls:[{key:'balanced',label:'Branch allocation',options:[[true,'Balanced'],[false,'Unequal']]}]}),
  scene('thermal-limits','Current becomes heat along the route','mechanism','D04.2','current-and-rating','Conductor loss rises with current squared for a fixed resistance. Heating also depends on enclosure, ambient temperature and the load waveform. Harmonic current adds RMS current and can increase transformer eddy losses. The usable limit has to reflect those operating conditions; an average kW reading is insufficient.'),
  scene('reserve','Hold power for future racks','balance','D04.2','current-and-rating','A supplied 1,200 kVA usable limit with 20% held for expansion leaves 960 kVA for current demand. At PF 0.90 and 96% conversion efficiency, that permits 829.44 kW at the DC output. This is a chosen expansion reservation, separate from environmental derating and from spare capacity for equipment loss.',{controls:[{key:'reserve',label:'Held for expansion',options:[[0,'0%'],[.2,'20%']]}]}),
  scene('conversion-locations','Choose which part of the route carries DC','architecture','D04.3','conversion-placement','With rack conversion, AC reaches each rack. With a sidecar, AC reaches the row and a short DC connection reaches compatible racks. Central rectification makes a longer downstream route DC. Every changed segment needs the correct voltage, connectors, switching, protection and load interface.',{controls:[{key:'placement',label:'AC/DC location',options:[['rack','Rack'],['row','Row sidecar'],['central','Electrical room']]}]}),
  scene('green-dc','Zurich-West supplied compatible servers with DC in 2012','architecture','D04.3','conversion-placement','ABB and Green opened a one-megawatt DC system for the 1,100 square meter Zurich-West expansion in May 2012. HP supplied DC-capable servers and storage. This is a built historical example of moving rectification upstream. It does not establish a universal efficiency gain or a current 800 V deployment.',{case:'green'}),
  scene('green-path','The central rectifier still contained a transformer','mechanism','D04.3','conversion-placement','ABB’s technical account describes a 16 kV AC input, a 1,100 kVA dry transformer inside the central unit, followed by thyristor rectifier modules and DC distribution to compatible IT. The system diagram labels 380 V DC; the text gives 400 V open-circuit. Those describe different conditions. The word rectifier names a package here, not the absence of transformation.',{case:'green'}),
  scene('loss-ledger','Compare both paths at the same output','balance','D04.3','conversion-placement','For a common 1 MW DC output, Path A combines assumed 98% distribution and 96% rack conversion. Path B combines central conversion and 99% DC distribution. At 97.5% central efficiency B uses less input. At 94% it uses more. The comparison turns on supplied operating-point efficiencies, not the location label.',{controls:[{key:'conversionEfficiency',label:'Central converter efficiency',options:[[.975,'97.5%'],[.94,'94%']]}]}),
  scene('relocated-heat','Moving the converter moves its heat','comparison','D04.3','conversion-placement','For 900 kW DC at 96% efficiency, converter loss is 37.5 kW. Move exactly that same converter from the rack to an electrical room: the local heat load moves, but source power does not change. A smaller rack heat account alone cannot establish a facility energy saving.',{controls:[{key:'moved',label:'Converter location',options:[[false,'At rack'],[true,'Electrical room']]}]}),
  scene('phase-opening','Check the service and the branch separately','balance','D04.4','read-the-power-train','The phase has a supplied 6.0 MW service limit and 4.8 MW IT-output branch limit. Its demand is 4.6 MW IT, 1.0 MW auxiliaries and 0.2 MW electrical losses. Facility demand is 5.8 MW, leaving 0.2 MW at both boundaries for different reasons.'),
  scene('hot-weather','The pumps can consume the remaining service margin','counterexample','D04.4','read-the-power-train','Keep 4.6 MW IT and the supplied 0.2 MW loss estimate fixed. Raising auxiliaries from 1.0 MW to 1.4 MW makes facility input 6.2 MW, exceeding the service while the IT branch still fits. The response must change the supported operating envelope or the upstream service.',{controls:[{key:'weather',label:'Auxiliary demand',options:[['normal','1.0 MW'],['hot','1.4 MW']]}]}),
  scene('expansion-decision','What releases the next 0.5 MW of IT?','transfer','D04.4','read-the-power-train','The extension adds 0.5 MW IT, 0.1 MW auxiliaries and 0.02 MW electrical losses to the normal phase. Required facility input is 6.42 MW and IT output 5.1 MW. Choose an intervention before revealing the two demand-to-limit comparisons. Both service and downstream branch must be resolved; if not, hold the extension.',{controls:[{key:'decision',label:'Proposed release',options:[['service','Service → 10 MW'],['branch','IT branch → 5.5 MW'],['both','Upgrade both']]}],reveal:'reveal'}),
  scene('distribution-handoff','What happens when this path is interrupted?','transfer','D04.1','read-the-power-train','The normal-load account establishes voltage interfaces, connected loads and usable limits. The next chapter changes the operating state: which paths keep IT and the supporting pumps powered when supply or equipment is unavailable? Preserve the same boundaries when adding storage and alternate paths.'),
];
